import type { BaseMessage } from "@langchain/core/messages";
import { trimMessages } from "@langchain/core/messages";
import { HumanMessage } from "@langchain/core/messages";
import { createReactAgent } from "@langchain/langgraph/prebuilt";
import { Annotation, StateGraph } from "@langchain/langgraph";
import { IntentDiscoveryGraph } from "./intent";
import { PostgresCheckpoint } from "../memory";
import { Query } from "../agents/compiler";
import { GPT4oMini } from "../models";

/**
 * Represents the root state of the AI graph, encapsulating all relevant properties
 * for managing the conversation and its persistence.
 *
 * @property query - The current query object being processed.
 * @property messages - An array of base messages exchanged in the conversation.
 * @property persisted - Indicates whether the current state has been persisted.
 * @property userInput - The latest input provided by the user.
 * @property assistant - The latest response generated by the assistant.
 * @property finish - Flag indicating whether the conversation has finished.
 */
const GraphState = Annotation.Root({
  query: Annotation<typeof Query>,
  messages: Annotation<Array<BaseMessage>>,
  persisted: Annotation<boolean>,
  userInput: Annotation<string>,
  assistant: Annotation<string>,
  finish: Annotation<boolean>,
});

/**
 * Evaluates the status of the assistant based on the provided graph state.
 *
 * @param state - The current state object of type `GraphState.State`.
 * @returns Returns `"MORE_CHAT"` if the assistant does not include `"READY_DATA"`, otherwise returns `"OK"`.
 */
const evalStatus = (state: typeof GraphState.State) => {
  if (!state?.assistant.includes("READY_DATA")) return "MORE_CHAT";
  return "OK";
};

/**
 * Creates an assistant agent node for the Watchit Discovery Assistant.
 *
 * The agent is designed to infer and phrase the user's viewing intention with rich detail,
 * following specific conversational and output guidelines. It uses a custom prompt to ensure
 * responses are empathetic, helpful, and context-aware, producing a single first-person sentence
 * summarizing the user's intent, genre/style, tone/mood, and constraints.
 *
 * The agent:
 * - Asks clarifying questions if essential information is missing.
 * - Refuses or pivots on inappropriate topics (sexuality, racism, hate speech, graphic violence).
 * - Avoids lists, repetition, and JSON output.
 * - Tracks past intents without merging unless explicitly requested.
 * - Trims message history to control token usage and costs.
 *
 * @returns An asynchronous function that processes the current graph state, interacts with the agent,
 *          and returns the updated messages and assistant response.
 */
const createAssistantAgentNode = () => {
  const openAIKey = process.env.API_OPENAI_API_KEY;

  /**
   * Initializes a GPT-4o Mini assistant instance using the provided OpenAI API key.
   *
   * @remarks
   * This assistant can be used to interact with the GPT-4o Mini model for AI-powered tasks.
   *
   * @param openAIKey - The API key required to authenticate requests to the OpenAI service.
   * @returns An instance of the GPT-4o Mini assistant.
   */
  const assistant = GPT4oMini({ apiKey: openAIKey });

  const prompt = `
        You are Watchit Discovery Assistant for watchit.movie. You are kind, empathetic, and helpful. 
        Your goal: infer and phrase the user's viewing intention with rich detail.  

        ### Output
        - Produce ONE first-person sentence (≤30 words) that includes intention, genre/style, tone/mood, and ≥2 constraints (duration, occasion/context, sentiment/intensity, language, time-of-day).  
        - Always add 2-3 vivid adjectives.  
        - Mention viewing time if possible (short/quick, long/deep, tonight, now).  
        - End with READY_DATA only when the intent is fully clear.  
        - The final line must be single-sentence, <30 words, ending with READY_DATA.  

        ### Interaction
        - Be conversational; ask max one clarifying question if essentials are missing (no READY_DATA in questions).  
        - Refuse or pivot if asked about sexuality, racism, hate speech, or graphic violence.  
        - If the user asks broadly (“what do you recommend?”), reply with one clarifying question only.  
        - No lists, no repetition, no JSON.  

        ### Memory
        - Track past intents but do not merge unless the user explicitly says so.  
        - If they change their mind, briefly acknowledge the shift, but never include past intents in the final READY_DATA line.          

    `;

  const model = assistant.build();
  const agent = createReactAgent({
    llm: model,
    tools: [],
    prompt: prompt,
  });

  return async (state: typeof GraphState.State) => {
    const inputMessage = new HumanMessage(state.userInput ?? "");
    const messages = (state.messages ?? []).concat([inputMessage]);

    // We need to avoid keep long chats to reduce costs!
    const trimmed = await trimMessages(messages, {
      maxTokens: parseInt(process.env.API_MAX_TOKENS_HISTORY ?? "256"),
      strategy: "last",
      tokenCounter: model,
      includeSystem: false,
    });

    const response = await agent.invoke({ messages: trimmed });
    const lastMessage = response.messages.at(-1) as BaseMessage;

    return {
      finish: false,
      messages: response.messages,
      assistant: lastMessage.content,
    };
  };
};

const RootGraph = (config: any) => {
  return new StateGraph(GraphState)
    .addNode("intent_discovery_node", IntentDiscoveryGraph(config))
    .addNode("assistant_node", createAssistantAgentNode())
    .addEdge("__start__", "assistant_node")
    .addEdge("intent_discovery_node", "__end__")
    .addConditionalEdges("assistant_node", evalStatus, {
      MORE_CHAT: "__end__",
      OK: "intent_discovery_node",
    })
    .compile(config);
};

export const RootAgent = () => {
  return {
    name: "RootAgent",
    graph: (c: any) => RootGraph(c),
    memory: () => PostgresCheckpoint(),
  };
};

export type RootGraphType = ReturnType<typeof RootGraph>;
export type RootAgentType = ReturnType<typeof RootAgent>;
